# Kept here as they were when this ran: which credits each type of event offers.
_ROLES = {"theater": ("author", "music", "lyrics"), "dance": ("author", "music", "lyrics"),
          "comedy": ("author",)}


def book_becomes_author(apps, schema_editor):
    """A play's Book people join its Authors, and Book credits on events become Author."""
    Play = apps.get_model("events", "Play")
    EventArtist = apps.get_model("events", "EventArtist")
    for play in Play.objects.prefetch_related("book_by"):
        people = list(play.book_by.all())
        if people:
            play.authors.add(*people)
    EventArtist.objects.filter(role="book").update(role="author")


def credit_play_creators(apps, schema_editor):
    """Every staging credits everyone who created its play (author, music, lyrics), in that role."""
    Event = apps.get_model("events", "Event")
    EventArtist = apps.get_model("events", "EventArtist")
    for event in Event.objects.exclude(play=None).select_related("play"):
        on_event = set(EventArtist.objects.filter(event=event).values_list("artist_id", flat=True))
        last = max([0, *EventArtist.objects.filter(event=event).values_list("billing_order", flat=True)])
        offered = _ROLES.get(event.event_type, ("author",) if event.event_type in ("other", "multicultural") else ())
        for role, people in (("author", event.play.authors), ("music", event.play.music_by),
                             ("lyrics", event.play.lyrics_by)):
            if role not in offered:
                role = "author" if "author" in offered else "other"
            for artist in people.exclude(pk__in=on_event):
                last += 1
                on_event.add(artist.pk)
                EventArtist.objects.create(event=event, artist=artist, role=role, billing_order=last)


